CREATE VIRTUAL TABLE t1 USING fts4(matchinfo=fts3);INSERT INTO t1(rowid,content)VALUES(1,replace(hex(zeroblob(100000)),'00','zm ')),(2,replace(hex(zeroblob(100000)),'00','jk ')),(3,'zm zm agmckuiu uhzq nsab jk rrkx duszemmzl hyq jk'),(24,'jk zm agmckuiu urvysbnykk jk jk zm zm jk jk'),(52,'zm agmckuiu zexh fibokdry jk uhzq bu tugflixoex xnxhf sk'),(53,'zm zf uenvbm jk azavwm zm zm agmckuiu zm jk');WITH RECURSIVE c(x)AS(VALUES(1)UNION ALL SELECT x+1 FROM c WHERE x<1000)INSERT INTO t1(content)SELECT '' FROM c;UPDATE t1_segments SET block=zeroblob(length(block)) WHERE length(block)>10000;